import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第四册：流利英语 · Lesson 33 Education","description":"学习 平行结构与 not only…but also，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 33 Education","description":"学习 平行结构与 not only…but also，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 平行结构与 not only…but also，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 32 Galileo reborn","link":"/life/english/new-concept/book-4/unit-04/lesson-032"},"next":{"text":"第四册：流利英语 · Lesson 34 Adolescence","link":"/life/english/new-concept/book-4/unit-05/lesson-034"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 32 Galileo reborn","link":"/life/english/new-concept/book-4/unit-04/lesson-032"},"next":{"text":"第四册：流利英语 · Lesson 34 Adolescence","link":"/life/english/new-concept/book-4/unit-05/lesson-034"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-05/lesson-033.md","filePath":"life/english/new-concept/book-4/unit-05/lesson-033.md"}'),i={name:"life/english/new-concept/book-4/unit-05/lesson-033.md"};function l(s,e,r,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-33-education" tabindex="-1">第四册：流利英语 · Lesson 33 Education <a class="header-anchor" href="#第四册-流利英语-·-lesson-33-education" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 33 Education&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元 5</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕教育目标与学习方式阅读论述，区分记住信息、掌握方法与形成判断能力。不要仅凭某一种课堂活动就概括教育的全部价值；练习把目标转为可观察的学习成果。重点使用平行结构列举目标，让各项在语法和逻辑层面都能相互比较。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>curriculum</td><td>/kəˈrɪkjələm/</td><td>n.</td><td>课程体系</td><td>design a curriculum</td></tr><tr><td>inquiry</td><td>/ɪnˈkwaɪəri/</td><td>n.</td><td>探究</td><td>independent inquiry</td></tr><tr><td>assessment</td><td>/əˈsesmənt/</td><td>n.</td><td>评估</td><td>formative assessment</td></tr><tr><td>judgement</td><td>/ˈdʒʌdʒmənt/</td><td>n.</td><td>判断力</td><td>exercise judgement</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>learn by doing — 在实践中学习</li><li>build on — 在已有基础上发展</li></ul><h2 id="语法讲解-平行结构与-not-only-but-also" tabindex="-1">语法讲解：平行结构与 not only…but also <a class="header-anchor" href="#语法讲解-平行结构与-not-only-but-also" aria-label="Permalink to &quot;语法讲解：平行结构与 not only…but also&quot;">​</a></h2><p>由 and、or、not only…but also 连接的成分应在语法层级上平行，例如 to question, to compare and to explain，不能混成 to question, comparing and an explanation。not only 放句首引出完整分句时，该分句要部分倒装；放在谓语内部连接宾语时一般不倒装。平行不只关乎词形，也要求项目处于同一逻辑类别，避免把学习行为与资源条件无说明地混列。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The course teaches students to question claims, compare sources and explain their conclusions.</p></blockquote><p>这门课程教学生质疑主张、比较来源并解释结论。</p><p>to 后三个动词 question、compare、explain 并列，共享不定式标记 to，宾语分别对应各动作。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>to question claims, comparing sources and explanations 不平行；应统一为三个动词短语。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在 question claims、compare sources、explain conclusions 三段保持相似节奏；最后一项用降调收束列表。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Students will learn to ask questions, compare evidence and defend a conclusion. They will work with two short reports on the same issue. A final discussion will show how clearly they can explain their reasoning.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为一个研究课设计三句学习目标，包含平行动词和一种评估方法。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>目标、材料与评估对应，平行结构使三个能力要求清晰可比。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改正：Students learn to observe, recording and to explain.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Students learn to observe, record and explain.</p><p><strong>解析：</strong> 三个并列动词共享 to。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：Not only ___ she read the report, but she also checked its sources.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> did</p><p><strong>解析：</strong> 句首 not only 触发过去时部分倒装。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>示例列出哪三个可观察行为？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 质疑主张、比较来源、解释结论。</p><p><strong>解析：</strong> 三个并列动作均能在学生产出中观察。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：平行结构与 not only…but also。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-032">上一课</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-05/lesson-034">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",l]]);export{p as __pageData,b as default};
